80	// SecondBrain/Knowledge, the Mac memory slug, morning-briefings, KeystoneOS
81	// decisions and .codex/memories were never indexed by this hook. Fixed
82	// 2026-08-14. A fallback now also writes to .errors.log — see resolvePaths.
83	// 2026-09-10: DEV lives at ~/DEV on the Mac and ~/Desktop/DEV on the Windows
84	// laptop (both machines active again). Resolve whichever exists so neither
85	// machine silently falls back. Paths in the config may use {DEV} as well as {HOME}.
86	const DEV_ROOT = [
87	  path.join(os.homedir(), 'DEV'),
88	  path.join(os.homedir(), 'Desktop', 'DEV'),
89	].find(p => { try { return fs.statSync(path.join(p, 'KeystoneOS')).isDirectory(); } catch (_) { return false; } })
90	  || path.join(os.homedir(), 'DEV');
