92	// which only exists on the Mac; on Windows the vault is ~/Desktop/SecondBrain,
93	// so the existsSync filter below silently dropped all three vault paths and the
94	// vault was never indexed there. Paths may now use {VAULT}, resolved the same way.
95	const VAULT_ROOT = [
96	  path.join(os.homedir(), 'SecondBrain'),
97	  path.join(os.homedir(), 'Desktop', 'SecondBrain'),
98	].find(p => { try { return fs.statSync(p).isDirectory(); } catch (_) { return false; } })
99	  || path.join(os.homedir(), 'SecondBrain');
100	const KEYSTONE_INDEX_CONFIG = path.join(
101	  DEV_ROOT, 'KeystoneOS', 'data', 'memory-index-paths.json'
102	);
