104	function resolvePaths() {
105	  // Mac-correct emergency set, used only when the config above is unreadable
106	  // or malformed. Kept deliberately small: these are the paths whose loss would
107	  // be felt first. The legacy C--Users-eric-rash slug is read-only Windows
108	  // history — indexing it is harmless and keeps that recall working.
109	  const fallback = [
110	    path.join(os.homedir(), '.claude', 'global-memory', 'transcripts'),
111	    path.join(os.homedir(), '.claude', 'projects', '-Users-kristinarash-DEV', 'memory'),
112	    path.join(os.homedir(), '.claude', 'projects', 'C--Users-eric-rash', 'memory'),
113	    path.join(os.homedir(), '.claude', 'claude-memory-compiler', 'daily'),
114	    path.join(os.homedir(), '.claude', 'claude-memory-compiler', 'knowledge'),
115	    path.join(VAULT_ROOT, 'Knowledge'),
116	  ];
117	  try {
118	    const raw = fs.readFileSync(KEYSTONE_INDEX_CONFIG, 'utf8');
119	    const parsed = JSON.parse(raw);
120	    if (!Array.isArray(parsed.paths) || parsed.paths.length === 0) {
121	      logErr(`index config ${KEYSTONE_INDEX_CONFIG} has no usable paths — using built-in fallback (${fallback.length} paths)`);
122	      return fallback;
123	    }
124	    return parsed.paths.map(p => p.replace('{DEV}', DEV_ROOT).replace('{VAULT}', VAULT_ROOT).replace('{HOME}', os.homedir()).split('/').join(path.sep));
125	  } catch (e) {
126	    // Loud, not silent: a silent fallback is exactly how the Desktop/DEV drift
127	    // went unnoticed from the Windows migration until 2026-08-14.
128	    logErr(`index config unreadable (${KEYSTONE_INDEX_CONFIG}): ${(e && e.message ? e.message : String(e)).slice(0, 160)} — using built-in fallback (${fallback.length} paths)`);
