133	const PATHS = resolvePaths();
134	// Truncated each run, so it always shows the most recent index result and
135	// never grows. Check this if recent sessions aren't turning up in search.
136	const INDEX_LOG = path.join(os.homedir(), '.claude', 'global-memory', 'transcripts', '.memsearch-index.log');
