138	// block the full timeout waiting on memsearch's own lock and then time out. The
139	// lock is acquired ATOMICALLY (open 'wx') so only one winner indexes per cluster;
140	// late arrivals see EEXIST and skip immediately — that run covers their new
141	// content too. The owner PID is checked before a lock is reclaimed. Age is only
142	// a fallback for locks written by an older version that did not record a PID.
143	const LOCK_FILE = path.join(os.homedir(), '.claude', 'global-memory', 'transcripts', '.memsearch-index.lock');
