153	// guaranteed to clear overnight. Alarm only if even the nightly isn't keeping up.
154	const TIMEOUT_STREAK_THRESHOLD = 6;
155	// Clears every per-class streak file (see bumpTransientStreak).
156	function clearStreaks() {
157	  const dir = path.dirname(TIMEOUT_STREAK_FILE), base = path.basename(TIMEOUT_STREAK_FILE);
158	  try {
159	    for (const f of fs.readdirSync(dir)) {
160	      if (f === base || f.startsWith(base + '-')) { try { fs.unlinkSync(path.join(dir, f)); } catch (_) {} }
161	    }
162	  } catch (_) {}
163	}
164	// Signatures that mean "another writer holds milvus.db/LOCK", not "the database
165	// is damaged". Deliberately narrow: matched against the flock/lock-acquisition
166	// text, NOT against milvus-lite's wording "may not be compatible with Milvus
167	// Lite 3.x" — that same sentence is emitted for genuine incompatibility too, so
168	// matching it would mask real corruption as transient. A truly broken database
169	// produces none of these and still escalates immediately.
170	const LOCK_BUSY_RE = /DataDirLockedError|another process holds the lock|Resource temporarily unavailable|_acquire_lock|fcntl\.flock/i;
171	// macOS refuses to dlopen native libraries once shutdown starts ("code signature
172	// ... not valid for use in process: system is shutting down"). A session that
173	// ends during a restart hits this on onnxruntime's .so and memsearch rewords it
174	// as "requires onnxruntime. Install with: pip install". The install is fine;
175	// do not reinstall. Seen 2026-09-16 07:46:41, reboot at 07:46:56.
176	const SHUTDOWN_RE = /system is shutting down/i;
177	
178	// The first "SomethingError: ..." line of a traceback. memsearch wraps the real
179	// failure in two more exceptions, so the first 300 chars of stderr are only
180	// "Traceback ... File ... import onnxruntime" and never reach the cause.
181	function rootCause(text) {
182	  const m = (text || '').match(/^[\w.]*(?:Error|Exception): .*$/m);
183	  return m ? m[0] : (text || '');
184	}
185	
186	const existing = PATHS.filter(p => fs.existsSync(p));
187	// Say which configured paths are missing instead of dropping them silently.
188	// Logged to the index log (not .errors.log) because some entries are
189	// legitimately machine-specific, e.g. the other machine's memory slug.
190	const missing = PATHS.filter(p => !existing.includes(p));
191	if (existing.length === 0) process.exit(0);
192	
193	function isProcessAlive(pid) {
194	  if (!Number.isInteger(pid) || pid <= 0) return false;
195	  try {
196	    process.kill(pid, 0);
197	    return true;
198	  } catch (e) {
199	    return e && e.code === 'EPERM';
200	  }
201	}
202	
203	// --- Acquire the lock atomically. Only one process wins per cluster. ---
204	let haveLock = false;
205	try {
206	  const fd = fs.openSync(LOCK_FILE, 'wx'); // fails if the file already exists
207	  fs.writeSync(fd, String(process.pid));
208	  fs.closeSync(fd);
209	  haveLock = true;
210	} catch (e) {
211	  // Lock exists. If its owner is alive, skip regardless of age. Only reclaim a
212	  // dead owner (or an old lock with no readable owner PID).
213	  let ownerPid = null;
214	  try {
215	    ownerPid = Number.parseInt(fs.readFileSync(LOCK_FILE, 'utf8').trim(), 10);
216	  } catch (_) {}
217	  if (isProcessAlive(ownerPid)) process.exit(0);
218	
219	  let stale = false;
220	  try { stale = (Date.now() - fs.statSync(LOCK_FILE).mtimeMs) >= LOCK_STALE_MS; }
221	  catch (_) { stale = true; } // lock vanished between open and stat — race; treat as reclaimable
222	  if (!stale) process.exit(0);
223	  try {
224	    fs.unlinkSync(LOCK_FILE);
225	    const fd = fs.openSync(LOCK_FILE, 'wx');
226	    fs.writeSync(fd, String(process.pid));
227	    fs.closeSync(fd);
228	    haveLock = true;
229	  }
230	  catch (_) { process.exit(0); }
231	}
232	
233	function releaseLock() {
234	  if (haveLock) { try { fs.unlinkSync(LOCK_FILE); } catch (_) {} haveLock = false; }
235	}
236	
237	// Cooldown: at most one index START per COOLDOWN_MS. The lock alone only
238	// serialises runs — on 2026-09-28 it produced a back-to-back chain of 600s
239	// runs all day, each paying the full model load (2.7 GB working set, 3.1 GB
240	// peak) and starving the machine. Checked while holding the lock so two
241	// workers cannot both pass. Content from sessions inside the window waits for
242	// the next session end after it; the index is incremental, so nothing is lost.
243	const LAST_RUN_FILE = path.join(os.homedir(), '.claude', 'global-memory', 'transcripts', '.memsearch-last-run');
244	const COOLDOWN_MS = 30 * 60 * 1000;
245	try {
246	  if (Date.now() - fs.statSync(LAST_RUN_FILE).mtimeMs < COOLDOWN_MS) {
247	    releaseLock();
248	    process.exit(0);
249	  }
250	} catch (_) {} // no marker yet — first run
251	try { fs.writeFileSync(LAST_RUN_FILE, new Date().toISOString() + ` pid=${process.pid}\n`); } catch (_) {}
252	
253	try {
254	  const res = spawnSync('memsearch', ['index', ...existing], {
255	    // Avoid an intermediate cmd.exe. On timeout, the direct child is killed
256	    // instead of leaving an orphaned Python indexer behind.
257	    shell: false,
258	    windowsHide: true,
259	    encoding: 'utf8',
260	    // memsearch can print more than Node's 1 MiB default during a large
261	    // incremental catch-up. Preserve its output and exit status for diagnosis.
262	    maxBuffer: 32 * 1024 * 1024,
263	    // Runaway guard, not a budget. We are detached, so nothing is waiting on
264	    // this. Raised 600s -> 3h on 2026-10-07: on the Windows laptop under
265	    // memory pressure (1-2 GB free) indexing ran ~1.2 s/chunk, so every 600s
266	    // run was killed mid-progress (965 rows written across two runs, streak 9)
267	    // and a backlog could never clear. The PID lock already stops overlap and
268	    // the 30-min cooldown stops back-to-back chains, so a long run costs
269	    // nothing but its own memory. A timeout now really is a hang.
270	    timeout: 3 * 60 * 60 * 1000,
271	  });
272	
273	  const out = `${res.stdout || ''}${res.stderr || ''}`.trim();
274	  const skipped = missing.length ? `(skipped, not on this machine: ${missing.join(', ')})\n` : '';
275	  try { fs.writeFileSync(INDEX_LOG, skipped + (out ? out + '\n' : '(no output)\n')); } catch (_) {}
276	
277	  // Transient, self-healing failures (the next incremental index catches up)
278	  // escalate to .errors.log only after a consecutive streak. Two classes:
279	  // ETIMEDOUT (session-end contention) and Milvus-unreachable (Docker Desktop
280	  // hasn't started yet — morning scheduled sessions routinely end before the
281	  // Milvus containers are up; observed 2026-07-16 07:40, self-healed by 08:43).
282	  //
283	  // One counter per class (2026-10-07): a shared counter let a Milvus-outage
284	  // streak and a timeout streak add up and report as "ETIMEDOUT 9x" when they
285	  // were two different problems. ETIMEDOUT keeps the original file name so
286	  // memsearch-drain.ps1 and older state still line up; other classes get a
287	  // suffix. Any clean run (or hard error) clears every class.
288	  function streakFile(label) {
289	    if (label === 'ETIMEDOUT') return TIMEOUT_STREAK_FILE;
290	    return `${TIMEOUT_STREAK_FILE}-${label.replace(/[^a-z0-9]+/gi, '-').toLowerCase()}`;
291	  }
292	  function bumpTransientStreak(label, detail) {
293	    const file = streakFile(label);
294	    let streak = 0;
295	    try { streak = parseInt(fs.readFileSync(file, 'utf8'), 10) || 0; } catch (_) {}
296	    streak += 1;
297	    try { fs.writeFileSync(file, String(streak)); } catch (_) {}
298	    if (streak >= TIMEOUT_STREAK_THRESHOLD) {
299	      logErr(`index ${label} ${streak}x consecutively — indexing may not be keeping up: ${detail.slice(0, 200)}`);
300	    } else {
301	      try { fs.appendFileSync(INDEX_LOG, `(${label} — streak ${streak}/${TIMEOUT_STREAK_THRESHOLD}, next session catches up)\n`); } catch (_) {}
302	    }
303	  }
304	
305	  if (res.error && res.error.code === 'ETIMEDOUT') {
306	    bumpTransientStreak('ETIMEDOUT', res.error.message);
307	  } else if (res.error) {
308	    logErr(`index ${res.error.code || 'error'}: ${res.error.message.slice(0, 300)}`);
309	    clearStreaks();
310	  } else if (res.status !== 0 && /Fail connecting to server/i.test(out)) {
311	    bumpTransientStreak('Milvus unreachable', (res.stderr || out));
312	  } else if (res.status !== 0 && LOCK_BUSY_RE.test(out)) {
313	    // Another writer (nightly reindex, a second session, a manual index) holds
314	    // milvus.db/LOCK. Transient by definition — the next incremental run covers
315	    // this session's content. Previously this fell through to the hard-error
316	    // branch and spammed .errors.log; worse, milvus-lite words the lock error
317	    // as "may not be compatible with Milvus Lite 3.x", which has already caused
318	    // one destructive rebuild. Never treat this as corruption.
319	    bumpTransientStreak('index busy (lock held)', (res.stderr || out));
320	  } else if (res.status !== 0 && SHUTDOWN_RE.test(out)) {
321	    // Mac was restarting. Transient; the next session after boot catches up.
322	    bumpTransientStreak('system shutting down', rootCause(res.stderr || out));
323	  } else if (res.status !== 0) {
324	    logErr(`index exit ${res.status}: ${rootCause(res.stderr).slice(0, 300)} (full output: ${INDEX_LOG})`);
325	    clearStreaks();
326	  } else {
327	    // Clean run — reset the consecutive-timeout streak.
328	    clearStreaks();
329	  }
330	} finally {
331	  releaseLock();
332	}
333	
334	process.exit(0);
