// below, and resolvePaths now calls logErr on the fallback branch. If ERR_LOG
// were still declared further down it would be in the temporal dead zone at
// that moment, and logErr's own try/catch would swallow the ReferenceError —
// turning the loud fallback warning silent again.
const ERR_LOG = path.join(os.homedir(), '.claude', 'global-memory', 'transcripts', '.errors.log');

function logErr(msg) {
  try { fs.appendFileSync(ERR_LOG, `[${new Date().toISOString()}] memsearch-sync: ${msg}\n`); }
  catch (_) {}
}

// Single source of truth, shared with daily-backup.ps1 and the Codex hook.
// Was ~/Desktop/DEV on Windows; DEV lives at ~/DEV on the Mac. The stale path
// silently resolved to the fallback below for months after the migration, so
// SecondBrain/Knowledge, the Mac memory slug, morning-briefings, KeystoneOS
// decisions and .codex/memories were never indexed by this hook. Fixed
// 2026-08-14. A fallback now also writes to .errors.log — see resolvePaths.
// 2026-09-10: DEV lives at ~/DEV on the Mac and ~/Desktop/DEV on the Windows
// laptop (both machines active again). Resolve whichever exists so neither
// machine silently falls back. Paths in the config may use {DEV} as well as {HOME}.
const DEV_ROOT = [
  path.join(os.homedir(), 'DEV'),
  path.join(os.homedir(), 'Desktop', 'DEV'),
].find(p => { try { return fs.statSync(path.join(p, 'KeystoneOS')).isDirectory(); } catch (_) { return false; } })
  || path.join(os.homedir(), 'DEV');
// 2026-09-30: same drift, vault edition. The config said {HOME}/SecondBrain,
// which only exists on the Mac; on Windows the vault is ~/Desktop/SecondBrain,
// so the existsSync filter below silently dropped all three vault paths and the
// vault was never indexed there. Paths may now use {VAULT}, resolved the same way.
const VAULT_ROOT = [
  path.join(os.homedir(), 'SecondBrain'),
  path.join(os.homedir(), 'Desktop', 'SecondBrain'),
].find(p => { try { return fs.statSync(p).isDirectory(); } catch (_) { return false; } })
  || path.join(os.homedir(), 'SecondBrain');
const KEYSTONE_INDEX_CONFIG = path.join(
  DEV_ROOT, 'KeystoneOS', 'data', 'memory-index-paths.json'
);

function resolvePaths() {
  // Mac-correct emergency set, used only when the config above is unreadable
  // or malformed. Kept deliberately small: these are the paths whose loss would
  // be felt first. The legacy C--Users-eric-rash slug is read-only Windows
  // history — indexing it is harmless and keeps that recall working.
  const fallback = [
    path.join(os.homedir(), '.claude', 'global-memory', 'transcripts'),
    path.join(os.homedir(), '.claude', 'projects', '-Users-kristinarash-DEV', 'memory'),
    path.join(os.homedir(), '.claude', 'projects', 'C--Users-eric-rash', 'memory'),
    path.join(os.homedir(), '.claude', 'claude-memory-compiler', 'daily'),
    path.join(os.homedir(), '.claude', 'claude-memory-compiler', 'knowledge'),
    path.join(VAULT_ROOT, 'Knowledge'),
  ];
  try {
    const raw = fs.readFileSync(KEYSTONE_INDEX_CONFIG, 'utf8');
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed.paths) || parsed.paths.length === 0) {
      logErr(`index config ${KEYSTONE_INDEX_CONFIG} has no usable paths — using built-in fallback (${fallback.length} paths)`);
      return fallback;
    }
    return parsed.paths.map(p => p.replace('{DEV}', DEV_ROOT).replace('{VAULT}', VAULT_ROOT).replace('{HOME}', os.homedir()).split('/').join(path.sep));
  } catch (e) {
    // Loud, not silent: a silent fallback is exactly how the Desktop/DEV drift
    // went unnoticed from the Windows migration until 2026-08-14.
    logErr(`index config unreadable (${KEYSTONE_INDEX_CONFIG}): ${(e && e.message ? e.message : String(e)).slice(0, 160)} — using built-in fallback (${fallback.length} paths)`);
    return fallback;
  }
}

const PATHS = resolvePaths();
// Truncated each run, so it always shows the most recent index result and
// never grows. Check this if recent sessions aren't turning up in search.
const INDEX_LOG = path.join(os.homedir(), '.claude', 'global-memory', 'transcripts', '.memsearch-index.log');
// When several sessions end in a cluster, each spawnSync below would otherwise
// block the full timeout waiting on memsearch's own lock and then time out. The
// lock is acquired ATOMICALLY (open 'wx') so only one winner indexes per cluster;
// late arrivals see EEXIST and skip immediately — that run covers their new
// content too. The owner PID is checked before a lock is reclaimed. Age is only
// a fallback for locks written by an older version that did not record a PID.
const LOCK_FILE = path.join(os.homedir(), '.claude', 'global-memory', 'transcripts', '.memsearch-index.lock');
const LOCK_STALE_MS = 5 * 60 * 1000;
// A single ETIMEDOUT is self-healing (the next session's incremental index
// catches up) and usually just means session-end contention — three fired on
// 2026-07-08 alone while the index stayed healthy. Only escalate to .errors.log
// after this many CONSECUTIVE timeouts; the count lives in a state file and any
// clean run resets it. Non-timeout failures still escalate immediately.
const TIMEOUT_STREAK_FILE = path.join(os.homedir(), '.claude', 'global-memory', 'transcripts', '.memsearch-timeout-streak');
// Raised 3 -> 6 on 2026-07-24: the nightly KeystoneOS-DailyBackup task now runs
// an uncapped full reindex and resets this counter, so heavy-day backlogs are
// guaranteed to clear overnight. Alarm only if even the nightly isn't keeping up.
const TIMEOUT_STREAK_THRESHOLD = 6;
// Clears every per-class streak file (see bumpTransientStreak).
function clearStreaks() {
  const dir = path.dirname(TIMEOUT_STREAK_FILE), base = path.basename(TIMEOUT_STREAK_FILE);
  try {
    for (const f of fs.readdirSync(dir)) {
      if (f === base || f.startsWith(base + '-')) { try { fs.unlinkSync(path.join(dir, f)); } catch (_) {} }
    }
  } catch (_) {}
}
// Signatures that mean "another writer holds milvus.db/LOCK", not "the database
// is damaged". Deliberately narrow: matched against the flock/lock-acquisition
// text, NOT against milvus-lite's wording "may not be compatible with Milvus
// Lite 3.x" — that same sentence is emitted for genuine incompatibility too, so
// matching it would mask real corruption as transient. A truly broken database
// produces none of these and still escalates immediately.
const LOCK_BUSY_RE = /DataDirLockedError|another process holds the lock|Resource temporarily unavailable|_acquire_lock|fcntl\.flock/i;
// macOS refuses to dlopen native libraries once shutdown starts ("code signature
// ... not valid for use in process: system is shutting down"). A session that
// ends during a restart hits this on onnxruntime's .so and memsearch rewords it
// as "requires onnxruntime. Install with: pip install". The install is fine;
// do not reinstall. Seen 2026-09-16 07:46:41, reboot at 07:46:56.
const SHUTDOWN_RE = /system is shutting down/i;

// The first "SomethingError: ..." line of a traceback. memsearch wraps the real
// failure in two more exceptions, so the first 300 chars of stderr are only
// "Traceback ... File ... import onnxruntime" and never reach the cause.
function rootCause(text) {
  const m = (text || '').match(/^[\w.]*(?:Error|Exception): .*$/m);
  return m ? m[0] : (text || '');
}

const existing = PATHS.filter(p => fs.existsSync(p));
// Say which configured paths are missing instead of dropping them silently.
// Logged to the index log (not .errors.log) because some entries are
// legitimately machine-specific, e.g. the other machine's memory slug.
const missing = PATHS.filter(p => !existing.includes(p));
if (existing.length === 0) process.exit(0);

function isProcessAlive(pid) {
  if (!Number.isInteger(pid) || pid <= 0) return false;
  try {
    process.kill(pid, 0);
    return true;
  } catch (e) {
    return e && e.code === 'EPERM';
  }
}

// --- Acquire the lock atomically. Only one process wins per cluster. ---
let haveLock = false;
try {
  const fd = fs.openSync(LOCK_FILE, 'wx'); // fails if the file already exists
  fs.writeSync(fd, String(process.pid));
  fs.closeSync(fd);
  haveLock = true;
} catch (e) {
  // Lock exists. If its owner is alive, skip regardless of age. Only reclaim a
  // dead owner (or an old lock with no readable owner PID).
  let ownerPid = null;
  try {
    ownerPid = Number.parseInt(fs.readFileSync(LOCK_FILE, 'utf8').trim(), 10);
  } catch (_) {}
  if (isProcessAlive(ownerPid)) process.exit(0);

  let stale = false;
  try { stale = (Date.now() - fs.statSync(LOCK_FILE).mtimeMs) >= LOCK_STALE_MS; }
  catch (_) { stale = true; } // lock vanished between open and stat — race; treat as reclaimable
  if (!stale) process.exit(0);
  try {
    fs.unlinkSync(LOCK_FILE);
    const fd = fs.openSync(LOCK_FILE, 'wx');
    fs.writeSync(fd, String(process.pid));
    fs.closeSync(fd);
    haveLock = true;
  }
  catch (_) { process.exit(0); }
}

function releaseLock() {
  if (haveLock) { try { fs.unlinkSync(LOCK_FILE); } catch (_) {} haveLock = false; }
}

// Cooldown: at most one index START per COOLDOWN_MS. The lock alone only
// serialises runs — on 2026-09-28 it produced a back-to-back chain of 600s
// runs all day, each paying the full model load (2.7 GB working set, 3.1 GB
// peak) and starving the machine. Checked while holding the lock so two
// workers cannot both pass. Content from sessions inside the window waits for
// the next session end after it; the index is incremental, so nothing is lost.
const LAST_RUN_FILE = path.join(os.homedir(), '.claude', 'global-memory', 'transcripts', '.memsearch-last-run');
const COOLDOWN_MS = 30 * 60 * 1000;
try {
  if (Date.now() - fs.statSync(LAST_RUN_FILE).mtimeMs < COOLDOWN_MS) {
    releaseLock();
    process.exit(0);
  }
} catch (_) {} // no marker yet — first run
try { fs.writeFileSync(LAST_RUN_FILE, new Date().toISOString() + ` pid=${process.pid}\n`); } catch (_) {}

try {
  const res = spawnSync('memsearch', ['index', ...existing], {
    // Avoid an intermediate cmd.exe. On timeout, the direct child is killed
    // instead of leaving an orphaned Python indexer behind.
    shell: false,
    windowsHide: true,
    encoding: 'utf8',
    // memsearch can print more than Node's 1 MiB default during a large
    // incremental catch-up. Preserve its output and exit status for diagnosis.
    maxBuffer: 32 * 1024 * 1024,
    // Runaway guard, not a budget. We are detached, so nothing is waiting on
    // this. Raised 600s -> 3h on 2026-10-07: on the Windows laptop under
    // memory pressure (1-2 GB free) indexing ran ~1.2 s/chunk, so every 600s
    // run was killed mid-progress (965 rows written across two runs, streak 9)
    // and a backlog could never clear. The PID lock already stops overlap and
    // the 30-min cooldown stops back-to-back chains, so a long run costs
    // nothing but its own memory. A timeout now really is a hang.
    timeout: 3 * 60 * 60 * 1000,
  });

  const out = `${res.stdout || ''}${res.stderr || ''}`.trim();
  const skipped = missing.length ? `(skipped, not on this machine: ${missing.join(', ')})\n` : '';
  try { fs.writeFileSync(INDEX_LOG, skipped + (out ? out + '\n' : '(no output)\n')); } catch (_) {}

  // Transient, self-healing failures (the next incremental index catches up)
  // escalate to .errors.log only after a consecutive streak. Two classes:
  // ETIMEDOUT (session-end contention) and Milvus-unreachable (Docker Desktop
  // hasn't started yet — morning scheduled sessions routinely end before the
  // Milvus containers are up; observed 2026-07-16 07:40, self-healed by 08:43).
  //
  // One counter per class (2026-10-07): a shared counter let a Milvus-outage
  // streak and a timeout streak add up and report as "ETIMEDOUT 9x" when they
  // were two different problems. ETIMEDOUT keeps the original file name so
  // memsearch-drain.ps1 and older state still line up; other classes get a
  // suffix. Any clean run (or hard error) clears every class.
  function streakFile(label) {
    if (label === 'ETIMEDOUT') return TIMEOUT_STREAK_FILE;
    return `${TIMEOUT_STREAK_FILE}-${label.replace(/[^a-z0-9]+/gi, '-').toLowerCase()}`;
  }
  function bumpTransientStreak(label, detail) {
    const file = streakFile(label);
    let streak = 0;
    try { streak = parseInt(fs.readFileSync(file, 'utf8'), 10) || 0; } catch (_) {}
    streak += 1;
    try { fs.writeFileSync(file, String(streak)); } catch (_) {}
    if (streak >= TIMEOUT_STREAK_THRESHOLD) {
      logErr(`index ${label} ${streak}x consecutively — indexing may not be keeping up: ${detail.slice(0, 200)}`);
    } else {
      try { fs.appendFileSync(INDEX_LOG, `(${label} — streak ${streak}/${TIMEOUT_STREAK_THRESHOLD}, next session catches up)\n`); } catch (_) {}
    }
  }

  if (res.error && res.error.code === 'ETIMEDOUT') {
    bumpTransientStreak('ETIMEDOUT', res.error.message);
  } else if (res.error) {
    logErr(`index ${res.error.code || 'error'}: ${res.error.message.slice(0, 300)}`);
    clearStreaks();
  } else if (res.status !== 0 && /Fail connecting to server/i.test(out)) {
    bumpTransientStreak('Milvus unreachable', (res.stderr || out));
  } else if (res.status !== 0 && LOCK_BUSY_RE.test(out)) {
    // Another writer (nightly reindex, a second session, a manual index) holds
    // milvus.db/LOCK. Transient by definition — the next incremental run covers
    // this session's content. Previously this fell through to the hard-error
    // branch and spammed .errors.log; worse, milvus-lite words the lock error
    // as "may not be compatible with Milvus Lite 3.x", which has already caused
    // one destructive rebuild. Never treat this as corruption.
    bumpTransientStreak('index busy (lock held)', (res.stderr || out));
  } else if (res.status !== 0 && SHUTDOWN_RE.test(out)) {
    // Mac was restarting. Transient; the next session after boot catches up.
    bumpTransientStreak('system shutting down', rootCause(res.stderr || out));
  } else if (res.status !== 0) {
    logErr(`index exit ${res.status}: ${rootCause(res.stderr).slice(0, 300)} (full output: ${INDEX_LOG})`);
    clearStreaks();
  } else {
    // Clean run — reset the consecutive-timeout streak.
    clearStreaks();
  }
} finally {
  releaseLock();
}

process.exit(0);

